        elif a=="--intersect":
            inter=True
        elif a in ("-d","--delimiter"):
            i+=1
            if i>=len(rest):
                sys.stderr.write("Invalid arguments.\n\nUsage:\n    xsv headers [options] [<input>...]\n")
                sys.exit(1)
            d=rest[i]
            if len(d)!=1:
