        i+=1
    if not inputs:
        data=read_bytes(None)
        try:
            recs,offs=parse_csv(data, delim)
        except ValueError as e:
            sys.stderr.write(f"CSV error: {e}\n")
            sys.exit(1)
        if not recs:
            return
        hdr=recs[0]
        if just:
            for h in hdr:
                print(h)
        else:
            for idx,h in enumerate(hdr):
                print(f"{idx+1}\t{h}")
        return
    all_hdrs=[]
    for p in inputs:
        try:
            data=open(p,'rb').read() if p!="-" else sys.stdin.buffer.read()
        except:
            sys.stderr.write(f"failed to open {p}: No such file or directory (os error 2)\n")
