        if not recs:
            all_hdrs.append([])
        else:
            all_hdrs.append(recs[0])
    if inter:
        if not all_hdrs:
            return
        first=all_hdrs[0]
        seen=set()
        res=[]
        for h in first:
            if h in seen:
                continue
            ok=True
            for other in all_hdrs[1:]:
                if h not in other:
                    ok=False
                    break
            if ok:
                seen.add(h)
                res.append(h)
        for h in res:
            print(h)
    else:
        if len(inputs)>1:
            for hdr in all_hdrs:
                for h in hdr:
                    print(h)
        else:
            hdr=all_hdrs[0]
            if just:
                for h in hdr:
                    print(h)
            else:
                for idx,h in enumerate(hdr):
                    print(f"{idx+1}\t{h}")

