def cmd_select(rest):
    delim=44
    out=None
    no_headers=False
    sel=None
    inp=None
    after=False
    i=0
    while i < len(rest):
        a=rest[i]
        if not after and a=="--":
            after=True
            i+=1
            continue
        if not after and a in ("-h","--help"):
            sys.stdout.write(HELPS["select"])
            return
        elif not after and a in ("-n","--no-headers"):
            no_headers=True
        elif not after and a in ("-o","--output"):
            i+=1
            if i>=len(rest):
                sys.stderr.write("Invalid arguments.\n\nUsage:\n    xsv select [options] [--] <selection> [<input>]\n    xsv select --help\n")
                sys.exit(1)
            out=rest[i]
        elif not after and a.startswith("--output="):
            out=a.split("=",1)[1]
        elif not after and a.startswith("-o") and len(a)>2:
            out=a[2:]
        elif not after and a in ("-d","--delimiter"):
            i+=1
            if i>=len(rest):
                sys.stderr.write("Invalid arguments.\n\nUsage:\n    xsv select [options] [--] <selection> [<input>]\n    xsv select --help\n")
                sys.exit(1)
            d=rest[i]
            if len(d)!=1:
                sys.stderr.write(f"Could not convert '{d}' to a single ASCII character.\n")
                sys.exit(1)
            delim=ord(d)
        elif not after and a.startswith("-d") and len(a)>2:
            d=a[2:]
            if len(d)!=1:
                sys.stderr.write(f"Could not convert '{d}' to a single ASCII character.\n")
                sys.exit(1)
            delim=ord(d)
        elif not after and a.startswith("--delimiter="):
            d=a.split("=",1)[1]
            if len(d)!=1:
                sys.stderr.write(f"Could not convert '{d}' to a single ASCII character.\n")
                sys.exit(1)
            delim=ord(d)
        elif not after and a.startswith("-") and len(a)>1:
            sys.stderr.write(f"Unknown flag: '{a}'\n\nUsage:\n    xsv select [options] [--] <selection> [<input>]\n    xsv select --help\n")
            sys.exit(1)
        else:
            if sel is None:
                sel=a
            elif inp is None:
                inp=a
            else:
                sys.stderr.write("Invalid arguments.\n\nUsage:\n    xsv select [options] [--] <selection> [<input>]\n    xsv select --help\n")
                sys.exit(1)
        i+=1
    if sel is None:
        sys.stderr.write("Invalid arguments.\n\nUsage:\n    xsv select [options] [--] <selection> [<input>]\n    xsv select --help\n")
        sys.exit(1)
    if '"' in sel:
        in_q=False
        j=0
        while j < len(sel):
            if sel[j]=='"':
                if in_q:
                    if j+1 < len(sel) and sel[j+1]=='"':
                        j+=2
                        continue
                    else:
                        in_q=False
                else:
                    in_q=True
            j+=1
        if in_q:
            sys.stderr.write('Unclosed quote, missing closing ".\n')
            sys.exit(1)
    data=read_bytes(inp)
    try:
        recs,offs=parse_csv(data, delim)
    except ValueError as e:
        sys.stderr.write(f"CSV error: {e}\n")
        sys.exit(1)
    if not recs:
        return
    headers=[] if no_headers else recs[0]
    data_recs=recs if no_headers else recs[1:]
    num_cols=len(recs[0]) if recs else 0
    if not no_headers:
        num_cols=len(headers)
    invert=False
    sel_inner=sel
    if sel_inner.startswith('!'):
        invert=True
        sel_inner=sel_inner[1:]
    selected=[]
    if sel_inner:
        toks=split_selectors(sel_inner)
        for tok in toks:
            if not tok:
                continue
            r=split_range(tok)
            if r:
                left,right=r
                if not left:
                    sys.stderr.write("Expected end of field but got '-' instead.\n")
                    sys.exit(1)
                lr=resolve_item(left, headers, num_cols, no_headers)
                li=lr[0]
                if right=='':
                    for idx in range(li, num_cols):
                        selected.append(idx)
                else:
                    rr=resolve_item(right, headers, num_cols, no_headers)
                    ri=rr[0]
                    if li<=ri:
                        for idx in range(li, ri+1):
                            selected.append(idx)
                    else:
                        for idx in range(li, ri-1, -1):
                            selected.append(idx)
            else:
                selected.extend(resolve_item(tok, headers, num_cols, no_headers))
    if invert:
        s=set(selected)
        final=[i for i in range(num_cols) if i not in s]
    else:
        final=selected
    out_recs=[]
    if not no_headers:
        out_recs.append([headers[i] if i < len(headers) else "" for i in final])
    for rec in data_recs:
        out_recs.append([rec[i] if i < len(rec) else "" for i in final])
    # write
    if out is None:
        out_f=sys.stdout
        writer=csv.writer(out_f, quoting=csv.QUOTE_MINIMAL, lineterminator='\n')
        for rec in out_recs:
            writer.writerow(rec)
    else:
        with open(out,'w',newline='') as f:
            writer=csv.writer(f, quoting=csv.QUOTE_MINIMAL, lineterminator='\n')
            for rec in out_recs:
                writer.writerow(rec)

def cmd_cat(rest):
    if not rest:
        sys.stderr.write("Invalid arguments.\n\nUsage:\n    xsv cat rows    [options] [<input>...]\n    xsv cat columns [options] [<input>...]\n    xsv cat --help\n")
        sys.exit(1)
    if rest[0] in ("-h","--help"):
        sys.stdout.write(HELPS["cat"])
        return
    sub=rest[0]
    if sub not in ("rows","columns"):
        sys.stderr.write("Invalid arguments.\n\nUsage:\n    xsv cat rows    [options] [<input>...]\n    xsv cat columns [options] [<input>...]\n    xsv cat --help\n")
        sys.exit(1)
    is_rows=sub=="rows"
    delim=44
    out=None
    no_headers=False
    pad=False
    inputs=[]
    i=1
    while i < len(rest):
        a=rest[i]
        if a in ("-h","--help"):
            sys.stdout.write(HELPS["cat"])
            return
        elif a in ("-p","--pad"):
            pad=True
        elif a in ("-n","--no-headers"):
            no_headers=True
        elif a in ("-d","--delimiter"):
            i+=1
            if i>=len(rest):
                sys.stderr.write("Invalid arguments.\n\nUsage:\n    xsv cat rows    [options] [<input>...]\n    xsv cat columns [options] [<input>...]\n    xsv cat --help\n")
                sys.exit(1)
            d=rest[i]
            if len(d)!=1:
                sys.stderr.write(f"Could not convert '{d}' to a single ASCII character.\n")
                sys.exit(1)
            delim=ord(d)
        elif a.startswith("-d") and len(a)>2:
            d=a[2:]
            if len(d)!=1:
                sys.stderr.write(f"Could not convert '{d}' to a single ASCII character.\n")
                sys.exit(1)
            delim=ord(d)
        elif a.startswith("--delimiter="):
            d=a.split("=",1)[1]
            if len(d)!=1:
                sys.stderr.write(f"Could not convert '{d}' to a single ASCII character.\n")
                sys.exit(1)
            delim=ord(d)
        elif a in ("-o","--output"):
            i+=1
            if i>=len(rest):
                sys.stderr.write("Invalid arguments.\n\nUsage:\n    xsv cat rows    [options] [<input>...]\n    xsv cat columns [options] [<input>...]\n    xsv cat --help\n")
                sys.exit(1)
            out=rest[i]
        elif a.startswith("--output="):
            out=a.split("=",1)[1]
        elif a.startswith("-o") and len(a)>2:
            out=a[2:]
        elif a.startswith("-"):
            sys.stderr.write(f"Unknown flag: '{a}'\n\nUsage:\n    xsv cat rows    [options] [<input>...]\n    xsv cat columns [options] [<input>...]\n    xsv cat --help\n")
            sys.exit(1)
        else:
            inputs.append(a)
        i+=1
    # read all
    all_recs=[]
    for p in inputs if inputs else [None]:
        data=read_bytes(p) if p is not None else sys.stdin.buffer.read()
        try:
            recs,offs=parse_csv(data, delim)
        except ValueError as e:
            sys.stderr.write(f"CSV error: {e}\n")
            sys.exit(1)
        all_recs.append(recs)
    if not all_recs:
        return
    # open output
    out_f=open(out,'w',newline='') if out else sys.stdout
    writer=csv.writer(out_f, quoting=csv.QUOTE_MINIMAL, lineterminator='\n')
    if is_rows:
        if not all_recs[0]:
            return
        num_cols=len(all_recs[0][0]) if all_recs[0] else 0
        if not no_headers:
            writer.writerow(all_recs[0][0])
        for fi, recs in enumerate(all_recs):
            start = 0 if no_headers else (0 if fi==0 else 1)
            if fi==0 and not no_headers:
                start=1
            for rec in recs[start:]:
                if len(rec)!=num_cols:
                    sys.stderr.write(f"CSV error: found record with {len(rec)} fields, but the previous record has {num_cols} fields\n")
                    sys.exit(1)
                writer.writerow(rec)
    else:
        # columns
        # For columns, we treat all records including header
        max_rows = max(len(r) for r in all_recs) if pad else min(len(r) for r in all_recs)
        for r_idx in range(max_rows):
            combined=[]
            for recs in all_recs:
                if r_idx < len(recs):
                    combined.extend(recs[r_idx])
                else:
                    # pad with empty fields
                    cols = len(recs[0]) if recs else 0
                    combined.extend([""]*cols)
            writer.writerow(combined)

