                sys.stderr.write("Invalid arguments.\n\nUsage:\n    xsv sort [options] [<input>]\n")
                sys.exit(1)
            inp=a
        i+=1
    data=read_bytes(inp)
    try:
        recs,offs=parse_csv(data, delim)
    except ValueError as e:
        sys.stderr.write(f"CSV error: {e}\n")
        sys.exit(1)
    if not recs:
        return
    headers=[] if no_headers else recs[0]
    data_recs=recs if no_headers else recs[1:]
    num_cols=len(recs[0]) if recs else 0
    if not no_headers:
        num_cols=len(headers)
    sort_idxs=[]
    if sel:
        # handle inversion
        invert=False
        inner=sel
        if inner.startswith('!'):
            invert=True
            inner=inner[1:]
        sel_idxs=[]
        if inner:
            toks=split_selectors(inner)
            for tok in toks:
                if not tok:
                    continue
                r=split_range(tok)
                if r:
                    l,rp=r
                    if not l:
                        sys.stderr.write("Expected end of field but got '-' instead.\n")
                        sys.exit(1)
                    lr=resolve_item(l, headers, num_cols, no_headers)
                    li=lr[0]
                    if rp=='':
                        for idx in range(li, num_cols):
                            sel_idxs.append(idx)
                    else:
                        rr=resolve_item(rp, headers, num_cols, no_headers)
                        ri=rr[0]
                        if li<=ri:
                            for idx in range(li, ri+1):
                                sel_idxs.append(idx)
                        else:
                            for idx in range(li, ri-1, -1):
                                sel_idxs.append(idx)
                else:
                    sel_idxs.extend(resolve_item(tok, headers, num_cols, no_headers))
        if invert:
            s=set(sel_idxs)
            sort_idxs=[i for i in range(num_cols) if i not in s]
        else:
            sort_idxs=sel_idxs
    else:
        sort_idxs=list(range(num_cols))

    def sort_key(rec):
        keys=[]
        for c in sort_idxs:
            v=rec[c] if c < len(rec) else ""
            if numeric:
                try:
                    # try float
                    keys.append(float(v))
                except:
                    keys.append(v)
            else:
                keys.append(v)
        return tuple(keys)

    data_recs.sort(key=sort_key, reverse=rev)
    out_f=open(out,'w',newline='') if out else sys.stdout
    writer=csv.writer(out_f, quoting=csv.QUOTE_MINIMAL, lineterminator='\n')
    if not no_headers:
        writer.writerow(headers)
    for rec in data_recs:
        writer.writerow(rec)

