def split_range(tok):
    in_q=False
    in_b=False
    for i,ch in enumerate(tok):
        if ch=='"':
            if in_q:
                if i+1 < len(tok) and tok[i+1]=='"':
                    continue
                else:
                    in_q=False
            else:
                in_q=True
        elif ch=='[' and not in_q:
