    out_f=open(out,'w',newline='') if out else sys.stdout
    writer=csv.writer(out_f, quoting=csv.QUOTE_MINIMAL, lineterminator='\n')
    if not no_headers:
        writer.writerow(headers)
    for rec in data_recs:
        matched=False
        for c in search_cols:
            if c < len(rec) and pat.search(rec[c]):
                matched=True
                break
        if (matched and not invert) or (not matched and invert):
            writer.writerow(rec)

