        else:
            col_idxs=sel_idxs
    else:
        col_idxs=list(range(num_cols))

    # compute stats
    cols=[]
    for _ in range(num_cols):
        cols.append({"values":[], "sum":0.0, "min":None, "max":None, "min_len":None, "max_len":0, "count":0, "total":0, "is_int":True, "is_float":True})

    for rec in data_recs:
        for cidx in col_idxs:
