                    col["min_len"]=0
                else:
                    col["min_len"]=min(col["min_len"],0)
                continue
            col["count"]+=1
            col["values"].append(val)
            char_len=len(val)
            col["max_len"]=max(col["max_len"], char_len)
            if col["min_len"] is None:
                col["min_len"]=char_len
            else:
                col["min_len"]=min(col["min_len"], char_len)
