                try:
                    int(val)
                except:
                    col["is_int"]=False
            if col["is_float"]:
                try:
                    float(val)
                except:
                    col["is_float"]=False
            try:
                col["sum"]+=float(val)
            except:
                pass
            if col["min"] is None or val < col["min"]:
                col["min"]=val
            if col["max"] is None or val > col["max"]:
                col["max"]=val

    header_fields=["field","type","sum","min","max","min_length","max_length","mean","stddev"]
    if everything:
        header_fields=["field","type","sum","min","max","min_length","max_length","mean","stddev","median","mode","cardinality"]
