    writer=csv.writer(out_f, quoting=csv.QUOTE_MINIMAL, lineterminator='\n')
    writer.writerow(header_fields)

    for cidx in col_idxs:
        col=cols[cidx]
        field_name = str(cidx) if no_headers else (headers[cidx] if cidx < len(headers) else str(cidx))
        type_str = "Integer" if col["is_int"] and col["count"]>0 else ("Float" if col["is_float"] and col["count"]>0 else "Unicode")
        sum_str = ""
        if col["count"]>0:
            if type_str=="Integer":
                sum_str=str(int(col["sum"]))
            elif type_str=="Float":
                if col["sum"].is_integer():
                    sum_str=str(int(col["sum"]))
                else:
                    sum_str=str(col["sum"])
        min_str = col["min"] if col["min"] is not None else ""
        max_str = col["max"] if col["max"] is not None else ""
        min_len_str = str(col["min_len"]) if col["min_len"] is not None else ""
        max_len_str = str(col["max_len"])
        mean_str=""
        stddev_str=""
        if col["count"]>0 or nulls:
            denom = col["total"] if nulls else col["count"]
            if denom>0:
                mean = col["sum"]/denom
                mean_str = str(int(mean)) if float(mean).is_integer() else str(mean)
                # stddev
                var=0.0
                n=0
                for v in col["values"]:
                    try:
                        f=float(v)
                        var+=(f-mean)**2
                        n+=1
                    except:
                        pass
                total_n = denom if nulls else n
                if total_n>0:
                    stddev = math.sqrt(var/total_n)
                    stddev_str=str(stddev)
        out_rec=[field_name, type_str, sum_str, min_str, max_str, min_len_str, max_len_str, mean_str, stddev_str]
        if everything:
            # median
            nums=[float(v) for v in col["values"] if v!='' and _is_float(v)]
            if nums:
                nums.sort()
                mid=len(nums)//2
                if len(nums)%2==0:
                    m=(nums[mid-1]+nums[mid])/2.0
                    median_str=str(int(m)) if m.is_integer() else str(m)
                else:
                    m=nums[mid]
                    median_str=str(int(m)) if m.is_integer() else str(m)
            else:
                median_str=""
            # mode
            freq={}
            for v in col["values"]:
                freq[v]=freq.get(v,0)+1
            if not freq:
                mode_str=""
            else:
                max_c=max(freq.values())
                if max_c<=1:
                    mode_str="N/A"
                else:
                    # first encountered with max
                    mode_str=""
                    for v in col["values"]:
                        if freq[v]==max_c:
                            mode_str=v
                            break
            # cardinality
            card_str=str(len(set(col["values"])))
            out_rec.append(median_str)
            out_rec.append(mode_str)
            out_rec.append(card_str)
        else:
            if med:
                nums=[float(v) for v in col["values"] if v!='' and _is_float(v)]
                if nums:
                    nums.sort()
                    mid=len(nums)//2
                    if len(nums)%2==0:
                        m=(nums[mid-1]+nums[mid])/2.0
                        median_str=str(int(m)) if m.is_integer() else str(m)
                    else:
                        m=nums[mid]
                        median_str=str(int(m)) if m.is_integer() else str(m)
                else:
                    median_str=""
                out_rec.append(median_str)
            if mode:
                freq={}
                for v in col["values"]:
                    freq[v]=freq.get(v,0)+1
                if not freq:
                    mode_str=""
                else:
                    max_c=max(freq.values())
                    if max_c<=1:
                        mode_str="N/A"
                    else:
                        mode_str=""
                        for v in col["values"]:
                            if freq[v]==max_c:
                                mode_str=v
                                break
                out_rec.append(mode_str)
            if card:
                out_rec.append(str(len(set(col["values"]))))
        writer.writerow(out_rec)

