    if inp and inp!="-" and os.path.exists(inp+".idx") and check_stale(inp):
        sys.stderr.write("The CSV file was modified after the index file. Please re-create the index.\n")
        sys.exit(1)
    data=read_bytes(inp)
    try:
        recs,offs=parse_csv(data, delim)
    except ValueError as e:
        sys.stderr.write(f"CSV error: {e}\n")
        sys.exit(1)
    if not recs:
        w=open_out(out)
        write_record(["field","value","count"], f=w)
        return
    headers=[] if no_headers else recs[0]
    data_recs=recs if no_headers else recs[1:]
    num_cols=len(recs[0]) if recs else 0
    if not no_headers:
        num_cols=len(headers)
    col_idxs=[]
    if sel:
        invert=False
        inner=sel
        if inner.startswith('!'):
            invert=True
            inner=inner[1:]
        sel_idxs=[]
        if inner:
            toks=split_selectors(inner)
            for tok in toks:
                if not tok:
                    continue
                r=split_range(tok)
                if r:
                    l,rp=r
                    if not l:
                        sys.stderr.write("Expected end of field but got '-' instead.\n")
                        sys.exit(1)
                    lr=resolve_item(l, headers, num_cols, no_headers)
                    li=lr[0]
                    if rp=='':
                        for idx_ in range(li, num_cols):
                            sel_idxs.append(idx_)
                    else:
                        rr=resolve_item(rp, headers, num_cols, no_headers)
                        ri=rr[0]
                        if li<=ri:
                            for idx_ in range(li, ri+1):
                                sel_idxs.append(idx_)
                        else:
                            for idx_ in range(li, ri-1, -1):
                                sel_idxs.append(idx_)
                else:
                    sel_idxs.extend(resolve_item(tok, headers, num_cols, no_headers))
        if invert:
            s=set(sel_idxs)
            col_idxs=[i for i in range(num_cols) if i not in s]
        else:
            col_idxs=sel_idxs
    else:
        col_idxs=list(range(num_cols))
    freq_maps=[{} for _ in range(num_cols)]
    for rec in data_recs:
        for actual in col_idxs:
            if actual>=len(rec):
                continue
            val=rec[actual]
            if no_nulls and val=='':
                continue
            key = "(NULL)" if val=='' else val
            freq_maps[actual][key]=freq_maps[actual].get(key,0)+1
    out_recs=[]
    for actual in col_idxs:
        field_name = str(actual) if no_headers else (headers[actual] if actual < len(headers) else str(actual))
        items=list(freq_maps[actual].items())
        if asc:
            items.sort(key=lambda x: (x[1], x[0]))
        else:
            items.sort(key=lambda x: (-x[1], x[0]))
        lim = len(items) if limit==0 else min(limit, len(items))
        for val,cnt in items[:lim]:
            out_recs.append((field_name, val, cnt))
    w=open_out(out)
    write_record(["field","value","count"], f=w)
    for f_,v,c in out_recs:
        write_record([f_,v,str(c)], f=w)

