    i=0
    while i < len(rest):
        a=rest[i]
        if a in ("-h","--help"):
            sys.stdout.write(HELPS["join"])
            return
        elif a=="--no-case":
            no_case=True
        elif a=="--left":
            left=True
        elif a=="--right":
            right=True
        elif a=="--full":
            full=True
        elif a=="--cross":
            cross=True
        elif a=="--nulls":
            nulls=True
        elif a in ("-n","--no-headers"):
            no_headers=True
        elif a in ("-d","--delimiter"):
            i+=1
            if i>=len(rest):
                sys.stderr.write("Invalid arguments.\n\nUsage:\n    xsv join [options] <columns1> <input1> <columns2> <input2>\n    xsv join --help\n")
                sys.exit(1)
            d=rest[i]
            if len(d)!=1:
                sys.stderr.write(f"Could not convert '{d}' to a single ASCII character.\n")
                sys.exit(1)
            delim=ord(d)
        elif a.startswith("-d") and len(a)>2:
            d=a[2:]
            if len(d)!=1:
                sys.stderr.write(f"Could not convert '{d}' to a single ASCII character.\n")
                sys.exit(1)
            delim=ord(d)
        elif a.startswith("--delimiter="):
            d=a.split("=",1)[1]
            if len(d)!=1:
                sys.stderr.write(f"Could not convert '{d}' to a single ASCII character.\n")
                sys.exit(1)
            delim=ord(d)
        elif a in ("-o","--output"):
            i+=1
            if i>=len(rest):
                sys.stderr.write("Invalid arguments.\n\nUsage:\n    xsv join [options] <columns1> <input1> <columns2> <input2>\n    xsv join --help\n")
                sys.exit(1)
            out=rest[i]
        elif a.startswith("--output="):
            out=a.split("=",1)[1]
        elif a.startswith("-o") and len(a)>2:
            out=a[2:]
        elif a.startswith("-"):
            sys.stderr.write(f"Unknown flag: '{a}'\n\nUsage:\n    xsv join [options] <columns1> <input1> <columns2> <input2>\n    xsv join --help\n")
            sys.exit(1)
        else:
            if cols1 is None:
                cols1=a
            elif in1 is None:
                in1=a
            elif cols2 is None:
                cols2=a
            elif in2 is None:
                in2=a
            else:
                sys.stderr.write("Invalid arguments.\n\nUsage:\n    xsv join [options] <columns1> <input1> <columns2> <input2>\n    xsv join --help\n")
                sys.exit(1)
        i+=1
    if cols1 is None or in1 is None or cols2 is None or in2 is None:
        sys.stderr.write("Invalid arguments.\n\nUsage:\n    xsv join [options] <columns1> <input1> <columns2> <input2>\n    xsv join --help\n")
        sys.exit(1)
    ops = [left,right,full,cross].count(True)
    if ops>1:
        sys.stderr.write("Please pick exactly one join operation.\n")
        sys.exit(1)
    for p in [in1,in2]:
        if os.path.exists(p+".idx") and check_stale(p):
            sys.stderr.write("The CSV file was modified after the index file. Please re-create the index.\n")
            sys.exit(1)
    try:
        data1=open(in1,'rb').read()
    except:
        sys.stderr.write(f"failed to open {in1}: No such file or directory (os error 2)\n")
        sys.exit(1)
    try:
        data2=open(in2,'rb').read()
    except:
        sys.stderr.write(f"failed to open {in2}: No such file or directory (os error 2)\n")
        sys.exit(1)
    try:
        recs1,offs1=parse_csv(data1, delim)
    except ValueError as e:
        sys.stderr.write(f"CSV error: {e}\n")
        sys.exit(1)
    try:
        recs2,offs2=parse_csv(data2, delim)
    except ValueError as e:
        sys.stderr.write(f"CSV error: {e}\n")
        sys.exit(1)
    if not recs1 or not recs2:
        return
    hdr1=[] if no_headers else recs1[0]
    hdr2=[] if no_headers else recs2[0]
    r1=recs1 if no_headers else recs1[1:]
    r2=recs2 if no_headers else recs2[1:]
    n1=len(recs1[0]) if recs1 else 0
    n2=len(recs2[0]) if recs2 else 0
    if not no_headers:
        n1=len(hdr1)
        n2=len(hdr2)
    w=open_out(out)
    if not no_headers:
        write_record(hdr1+hdr2, f=w)
    if cross:
        for a_rec in r1:
            for b_rec in r2:
                write_record(a_rec+b_rec, f=w)
        return
    idx1=parse_cols(cols1, hdr1, n1, no_headers)
    idx2=parse_cols(cols2, hdr2, n2, no_headers)
    if len(idx1)!=len(idx2):
        sys.stderr.write("Both columns1 and columns2 must specify exactly the same number of columns.\n")
        sys.exit(1)
    # Build map for r2
    mp={}
    for i2, rec2 in enumerate(r2):
        skip=False
        key_parts=[]
        for c in idx2:
            if c>=len(rec2):
                continue
            v=rec2[c].strip()
            if not nulls and v=='':
                skip=True
                break
            kv=v.lower() if no_case else v
            key_parts.append(kv)
        if skip:
            continue
        key="\0".join(key_parts)
        mp.setdefault(key, []).append((i2, rec2))
    matched=[False]*len(r2)
    for rec1 in r1:
        skip=False
        key_parts=[]
        for c in idx1:
            if c>=len(rec1):
                continue
            v=rec1[c].strip()
            if not nulls and v=='':
                skip=True
                break
            kv=v.lower() if no_case else v
            key_parts.append(kv)
        if skip:
            if left or full:
                write_record(rec1+[""]*n2, f=w)
            continue
        key="\0".join(key_parts)
        lst=mp.get(key)
        if lst:
            for i2, rec2 in lst:
                matched[i2]=True
                write_record(rec1+rec2, f=w)
        else:
            if left or full:
                write_record(rec1+[""]*n2, f=w)
    if right or full:
        for i2, rec2 in enumerate(r2):
            if not matched[i2]:
                # check null skip
                skip=False
                for c in idx2:
                    if c>=len(rec2):
                        continue
                    v=rec2[c].strip()
                    if not nulls and v=='':
                        skip=True
                        break
                if skip:
                    continue
                write_record([""]*n1+rec2, f=w)

