    try:
        os.makedirs(outdir, exist_ok=True)
    except:
        sys.stderr.write(f"failed to open {outdir}: No such file or directory (os error 2)\n")
        sys.exit(1)
    writers={}
    for rec in data_recs:
        if col_idx>=len(rec):
            continue
        part_val=rec[col_idx]
