            part_val=part_val[:prefix]
        key=sanitize(part_val)
        filename=fname.replace("{}", key)
        full=os.path.join(outdir, filename)
        if key not in writers:
            f=open(full,'wb')
            # write header
            if not no_headers:
                hdr=[h for i,h in enumerate(headers) if not (drop and i==col_idx)]
                write_record(hdr, f=f)
            writers[key]=f
        else:
            f=writers[key]
        out_rec=[field for i,field in enumerate(rec) if not (drop and i==col_idx)]
        write_record(out_rec, f=f)

