    let mut rng = StdRng::seed_from_u64(seed);
    let mut reservoir: Vec<usize> = Vec::new();
    for i in 0..data_len {
        if i < k {
            reservoir.push(i);
        } else {
            let j = rng.gen_range(0..=i);
            if j < k {
                reservoir[j]=i;
            }
        }
    }
    reservoir
}
fn main() {
    // ten rows 0..9, k=1 seed0
    println!("reservoir 10,k1,seed0: {:?}", reservoir(10,1,0));
    println!("k=1 seed1: {:?}", reservoir(10,1,1));
    println!("k=1 seed2: {:?}", reservoir(10,1,2));
    println!("k=1 seed3: {:?}", reservoir(10,1,3));
    // For file a.csv with 2 rows, k=1 seed0 should be [0] or [1]?
    println!("2 rows k1 seed0: {:?}", reservoir(2,1,0));
    println!("2 rows k1 seed1: {:?}", reservoir(2,1,1));
}
